import math
import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Fixed problem geometry for this kernel (matches the reference CuTe kernel
# specialised for embedding_dimension == 1024, LANES == 32).
# ---------------------------------------------------------------------------
LANES = 32                       # warp width
DPER = 32                        # elements per lane  (D_MODEL / LANES)
D_MODEL = LANES * DPER           # 1024
ROWS_PER_BLOCK = 8               # query rows handled per block (one warp/row)
THREADS = LANES * ROWS_PER_BLOCK # 256 threads per block
COOP_ITERS = D_MODEL // THREADS  # 4  (cooperative K/V load iterations)

# ---------------------------------------------------------------------------
# Shared-memory layout for K/V tiles.
#
# The original layout packed fp16 values tightly (2 bytes / element).  Since
# the dot-product / accumulation loops access shared memory with a per-lane
# stride of exactly 2 bytes, adjacent lanes fall into the SAME 4-byte shared
# memory bank pair (bank_id = (lane*2)//4 = lane//2), producing a 2-way bank
# conflict on every one of the DPER=32 shared loads per K/V tile, repeated
# for every tile iteration of the flash-attention loop.  This is a hot path
# executed (N / ROWS_PER_BLOCK) * DPER * 2 times per block.
#
# To remove the conflict we pad each fp16 element out to a full 4-byte slot
# in shared memory (PAD_STRIDE = 4).  With this layout, lane*4 maps exactly
# one lane to one bank (bank_id = lane), eliminating the bank conflict
# entirely while leaving the actual stored/loaded values (u16) unchanged.
# Global-memory addressing (which is still tightly packed fp16, 2 bytes /
# element) is unaffected by this change.
# ---------------------------------------------------------------------------
PAD_STRIDE = 4                                  # bytes per element in shared mem (padded)
K_TILE_BYTES = D_MODEL * PAD_STRIDE             # bytes for one padded K (or V) tile
BUF_STRIDE = 2 * K_TILE_BYTES                   # bytes per ping-pong buffer slot (K tile + V tile)
BUF_STRIDE_LOG2 = BUF_STRIDE.bit_length() - 1   # log2(BUF_STRIDE); BUF_STRIDE is a power of two
SMEM_BYTES = 2 * BUF_STRIDE                     # two ping-pong buffers for software-pipelined K/V loads
STAGE_PER_ARRAY = THREADS * COOP_ITERS * 2       # bytes: contiguous per-thread cp.async staging region for K (or V)
STAGE_BYTES = 2 * STAGE_PER_ARRAY                # staging area for both K and V tiles (async landing zone)


def _off(x: int) -> str:
    return f"+{x}" if x else ""


def _gen_q_load() -> str:
    lines = []
    for i in range(DPER):
        off = _off(i * LANES * 2)
        lines.append(f"    ld.global.nc.u16 %hq{i}, [%rd12{off}];")
        lines.append(f"    cvt.f32.f16 %q{i}, %hq{i};")
    return "\n".join(lines)


def _gen_acc_init() -> str:
    return "\n".join(f"    mov.f32 %acc{i}, 0f00000000;" for i in range(DPER))


def _gen_coop_issue() -> str:
    # Asynchronous (cp.async, sm_80+) global -> shared staging copy.
    # Instead of round-tripping the vectorized per-thread K/V tile chunk
    # through registers (ld.global.v4 -> registers -> st.shared), the
    # 8-byte-per-thread K and V chunks are copied directly from global
    # memory into a small contiguous "staging" landing zone in shared
    # memory using the hardware async-copy engine.  This removes the
    # load from the normal register/ALU issue pipeline and lets the
    # copy run in the background while the SM continues issuing the
    # current tile's dot-product / softmax / PV-accumulate instructions.
    # The matching cp.async.wait_group + scatter-unpack (see
    # _gen_coop_unpack) is deferred until just before the staged data is
    # actually needed, maximising the overlap window with compute.
    lines = []
    lines.append("    cp.async.ca.shared.global [%r122], [%rd18], 8;")
    lines.append("    cp.async.ca.shared.global [%r123], [%rd19], 8;")
    lines.append("    cp.async.commit_group;")
    return "\n".join(lines)
def _gen_coop_unpack() -> str:
    # Wait for the async copy issued by _gen_coop_issue() to land in the
    # staging area, then scatter the tightly-packed staged halfwords out
    # to their bank-conflict-free, XOR-swizzled, padded destinations in
    # the real ping-pong K/V buffer.  The store-side destination
    # addressing (precomputed swizzled bases %r90..%r97) is unchanged
    # from the previous synchronous-load implementation.
    #
    # The COOP_ITERS=4 contiguous halfwords staged per thread (8 bytes)
    # are now pulled out of shared memory with a single vectorized
    # ld.shared.v4.u16 instead of four separate scalar ld.shared.u16
    # instructions.  This halves the number of shared-memory load
    # instructions issued on this hot path (executed on essentially
    # every flash-attention tile iteration) while reading the exact
    # same bytes from the exact same (naturally 8-byte aligned)
    # staging address, so the unpacked per-lane values are unchanged.
    lines = []
    lines.append("    cp.async.wait_group 0;")
    coopk_regs = ", ".join(f"%hcoopk{c}" for c in range(COOP_ITERS))
    coopv_regs = ", ".join(f"%hcoopv{c}" for c in range(COOP_ITERS))
    lines.append(f"    ld.shared.v4.u16 {{{coopk_regs}}}, [%r122];")
    lines.append(f"    ld.shared.v4.u16 {{{coopv_regs}}}, [%r123];")
    for c in range(COOP_ITERS):
        lines.append(f"    st.shared.u16 [%r{90 + c}], %hcoopk{c};")
        lines.append(f"    st.shared.u16 [%r{94 + c}], %hcoopv{c};")
    return "\n".join(lines)


def _gen_dot_product() -> str:
    # Break the single 32-long sequential FMA dependency chain into
    # DOT_GROUPS independent partial-sum chains so the instruction
    # scheduler can overlap FMA latency across groups (higher ILP)
    # instead of serialising all DPER multiply-adds into one long
    # dependent chain through a single accumulator register.  Each
    # element also gets its own cvt.f32.f16 destination register
    # (instead of reusing a single %f4 scratch register) to remove
    # artificial write-after-write dependencies between iterations.
    #
    # DOT_GROUPS is raised from 4 to 8 (GROUP_SIZE 4 instead of 8):
    # doubling the number of independent partial-sum accumulators
    # halves the length of each FMA dependency chain (from 8 dependent
    # FMAs down to 4), giving the instruction scheduler more
    # independent work to interleave and further hiding per-FMA
    # latency, at the cost of a slightly deeper (but still cheap,
    # log2(8)=3-level) final tree-reduction of the partial sums.
    DOT_GROUPS = 8
    GROUP_SIZE = DPER // DOT_GROUPS
    lines = []
    for i in range(DPER):
        base_reg = 100 + (i % 4)
        off = _off(i * LANES * PAD_STRIDE)
        lines.append(f"    ld.shared.u16 %hk{i}, [%r{base_reg}{off}];")
        lines.append(f"    cvt.f32.f16 %g{i}, %hk{i};")
    for g in range(DOT_GROUPS):
        base = g * GROUP_SIZE
        lines.append(f"    mul.f32 %gp{g}, %q{base}, %g{base};")
        for j in range(1, GROUP_SIZE):
            idx = base + j
            lines.append(f"    fma.rn.f32 %gp{g}, %q{idx}, %g{idx}, %gp{g};")
    lines.append("    add.f32 %gp0, %gp0, %gp1;")
    lines.append("    add.f32 %gp2, %gp2, %gp3;")
    lines.append("    add.f32 %gp4, %gp4, %gp5;")
    lines.append("    add.f32 %gp6, %gp6, %gp7;")
    lines.append("    add.f32 %gp0, %gp0, %gp2;")
    lines.append("    add.f32 %gp4, %gp4, %gp6;")
    lines.append("    add.f32 %f5, %gp0, %gp4;")
    return "\n".join(lines)


def _gen_warp_reduce() -> str:
    lines = []
    for off in (16, 8, 4, 2, 1):
        lines.append("    mov.b32 %r20, %f5;")
        lines.append(f"    shfl.sync.bfly.b32 %r21|%p0, %r20, {off}, 31, -1;")
        lines.append("    mov.b32 %f6, %r21;")
        lines.append("    add.f32 %f5, %f5, %f6;")
    return "\n".join(lines)


def _gen_acc_update() -> str:
    lines = []
    for i in range(DPER):
        base_reg = 104 + (i % 4)
        off = _off(i * LANES * PAD_STRIDE)
        lines.append(f"    ld.shared.u16 %hv{i}, [%r{base_reg}{off}];")
        lines.append(f"    cvt.f32.f16 %f13, %hv{i};")
        lines.append(f"    mul.f32 %acc{i}, %acc{i}, %f10;")
        lines.append(f"    fma.rn.f32 %acc{i}, %f12, %f13, %acc{i};")
    return "\n".join(lines)


def _gen_output_store() -> str:
    lines = []
    for i in range(DPER):
        off = _off(i * LANES * 2)
        lines.append(f"    mul.f32 %f15, %acc{i}, %f14;")
        lines.append(f"    cvt.rn.f16.f32 %ho{i}, %f15;")
        lines.append(f"    st.global.u16 [%rd13{off}], %ho{i};")
    return "\n".join(lines)


def _build_ptx() -> str:
    body = f"""
.version 8.7
.target sm_89
.address_size 64

// Flash-attention style fused SDPA kernel.
// One warp handles one query row; ROWS_PER_BLOCK warps per block cooperate
// to stage K/V tiles into shared memory.  Specialised for D_MODEL={D_MODEL},
// LANES={LANES}, DPER={DPER}, ROWS_PER_BLOCK={ROWS_PER_BLOCK}.
//
// Shared-memory K/V tiles are padded to PAD_STRIDE={PAD_STRIDE} bytes per
// fp16 element (instead of the natural 2 bytes) so that per-lane accesses
// with stride LANES*PAD_STRIDE map one lane to one shared-memory bank,
// removing the 2-way bank conflicts present in the tightly-packed layout.
.visible .entry flash_attn_kernel(
    .param .u64 p_Q,
    .param .u64 p_K,
    .param .u64 p_V,
    .param .u64 p_O,
    .param .u32 p_N,
    .param .u32 p_D,
    .param .f32 p_scale
)
// -----------------------------------------------------------------
// Launch-bound specialisation: the host-side launch glue always
// dispatches this kernel with block dimensions (LANES, ROWS_PER_BLOCK,
// 1) = (32, 8, 1) (see ModelNew.forward below).  Declaring this exact
// CTA shape via .reqntid lets ptxas specialise register allocation,
// index/bounds computation, and instruction scheduling for the known,
// fixed thread-block geometry instead of generating code that has to
// remain correct for an arbitrary block shape.  This is a semantics-
// preserving launch-configuration hint (no change to addressing,
// synchronization, or numerical behaviour) that can improve achieved
// occupancy / reduce register spilling relative to the unconstrained
// compilation used previously.
// -----------------------------------------------------------------
.reqntid 32, 8, 1
// -----------------------------------------------------------------
// Register-budget occupancy hint: this kernel is heavily unrolled
// (DPER=32-wide accumulator / dot-product / q-load state, deep
// software-pipelined K/V staging, and a large XOR-swizzle address
// book-keeping section) and is very likely register-bound to a
// single resident CTA per SM when compiled with an unconstrained
// register budget.  Capping the per-thread register budget at 128
// lets ptxas fit two 256-thread CTAs (256*128 = 32768 regs; two
// such CTAs = 65536 regs = the full sm_89 per-SM register file)
// resident on a single SM simultaneously instead of just one,
// giving the scheduler a second independent CTA's worth of warps
// to interleave in order to hide the residual global-memory /
// shared-memory / FMA latency that the intra-CTA double-buffered
// software pipeline does not fully cover on its own.  This is a
// semantics-preserving compiler budget hint only (no change to
// addressing, synchronization, or numerical behaviour); if 128
// registers is insufficient for some live ranges, ptxas will
// simply spill those specific values rather than altering
// program behaviour.
// -----------------------------------------------------------------
.maxnreg 128
{{
    .reg .pred %p<4>;
    .reg .b16 %hq<{DPER}>;
    .reg .b16 %hk<{DPER}>;
    .reg .b16 %hv<{DPER}>;
    .reg .b16 %ho<{DPER}>;
    .reg .b16 %hcoopk<{COOP_ITERS}>;
    .reg .b16 %hcoopv<{COOP_ITERS}>;
    .reg .f32 %q<{DPER}>;
    .reg .f32 %acc<{DPER}>;
    .reg .f32 %f<16>;
    .reg .b32 %r<140>;
    .reg .b64 %rd<22>;

    .shared .align 16 .b8 smem_buf[{SMEM_BYTES}];
    .shared .align 16 .b8 stage_buf[{STAGE_BYTES}];

    ld.param.u64 %rd0, [p_Q];
    ld.param.u64 %rd1, [p_K];
    ld.param.u64 %rd2, [p_V];
    ld.param.u64 %rd3, [p_O];
    ld.param.u32 %r0, [p_N];
    ld.param.u32 %r1, [p_D];
    ld.param.f32 %f0, [p_scale];

    cvta.to.global.u64 %rd0, %rd0;
    .reg .f32 %g<{DPER}>;
    .reg .f32 %gp<8>;
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;

    mov.u32 %r2, %tid.x;               // lane   (0..31)
    mov.u32 %r3, %tid.y;               // warp id / row within tile (0..7)
    mov.u32 %r4, %ctaid.x;             // row tile index
    mov.u32 %r5, %ctaid.y;             // combined (batch*head) index

    mad.lo.s32 %r6, %r4, {ROWS_PER_BLOCK}, %r3;   // q_row = tile*ROWS_PER_BLOCK + warp

    mul.lo.s32 %r7, %r1, 2;            // rowbytes  = D*2
    mul.lo.s32 %r8, %r0, %r7;          // NDbytes   = N*D*2

    mul.wide.s32 %rd4, %r5, %r8;       // bh_offset  = bh * NDbytes
    mul.wide.s32 %rd5, %r6, %r7;       // row_offset = q_row * rowbytes
    add.s64 %rd6, %rd4, %rd5;          // qoff = bh_offset + row_offset

    add.s64 %rd7, %rd0, %rd6;          // Qrow_ptr
    add.s64 %rd8, %rd1, %rd4;          // Kbh_ptr
    add.s64 %rd9, %rd2, %rd4;          // Vbh_ptr
    add.s64 %rd10, %rd3, %rd6;         // Orow_ptr

    mul.wide.s32 %rd11, %r2, 2;        // lane_off64 = lane*2
    add.s64 %rd12, %rd7, %rd11;        // Q_lane_ptr
    add.s64 %rd13, %rd10, %rd11;       // O_lane_ptr

{_gen_q_load()}

    mov.f32 %f2, 0fFF800000;           // m_i = -inf
    mov.f32 %f3, 0f00000000;           // l_i = 0
{_gen_acc_init()}

    mad.lo.s32 %r9, %r3, {LANES}, %r2;         // tid = warp*LANES + lane  (0..THREADS-1)
    mul.wide.s32 %rd14, %r9, {COOP_ITERS * 2};        // tid_off64 (global mem, contiguous per-thread group of COOP_ITERS elems)
    mov.u32 %r10, smem_buf;
    mov.u32 %r120, stage_buf;
    shl.b32 %r121, %r9, 3;                     // tid*8 (per-thread cp.async staging offset, 8B aligned)
    add.s32 %r122, %r120, %r121;               // stageK_addr (cp.async landing zone, per-thread)
    add.s32 %r123, %r122, {STAGE_PER_ARRAY};   // stageV_addr (cp.async landing zone, per-thread)
    // ---------------------------------------------------------------
    // XOR-swizzled shared-memory base addresses to remove the 4-way bank
    // conflict on the cooperative K/V store (see _gen_coop_load) while
    // keeping the already-conflict-free read-side addressing pattern.
    // For padded element index d (row=d>>5, col=d&31) the swizzled column
    // is (col XOR (row&3)); this is applied consistently to both the
    // store-side base (indexed by c = 0..COOP_ITERS-1) and the read-side
    // base (indexed by k = i%4) so that store and read agree on the same
    // physical shared-memory location for a given d.
    // ---------------------------------------------------------------
    mul.lo.s32 %r40, %r3, 512;                 // warp512 = warp*512  (store-side)
    shl.b32 %r41, %r2, 2;                      // lane4   = lane*4    (store-side)
    add.s32 %r42, %r41, 0;
    shr.u32 %r43, %r42, 5;
    and.b32 %r44, %r42, 31;
    xor.b32 %r45, %r44, %r43;
    shl.b32 %r46, %r45, 2;
    shl.b32 %r47, %r43, 7;
    add.s32 %r48, %r46, %r47;
    add.s32 %r48, %r48, %r40;
    add.s32 %r50, %r48, %r10;                  // K store base constant, c=0
    add.s32 %r54, %r50, {K_TILE_BYTES};        // V store base constant, c=0
    add.s32 %r42, %r41, 1;
    shr.u32 %r43, %r42, 5;
    and.b32 %r44, %r42, 31;
    xor.b32 %r45, %r44, %r43;
    shl.b32 %r46, %r45, 2;
    shl.b32 %r47, %r43, 7;
    add.s32 %r48, %r46, %r47;
    add.s32 %r48, %r48, %r40;
    add.s32 %r51, %r48, %r10;                  // K store base constant, c=1
    add.s32 %r55, %r51, {K_TILE_BYTES};        // V store base constant, c=1
    add.s32 %r42, %r41, 2;
    shr.u32 %r43, %r42, 5;
    and.b32 %r44, %r42, 31;
    xor.b32 %r45, %r44, %r43;
    shl.b32 %r46, %r45, 2;
    shl.b32 %r47, %r43, 7;
    add.s32 %r48, %r46, %r47;
    add.s32 %r48, %r48, %r40;
    add.s32 %r52, %r48, %r10;                  // K store base constant, c=2
    add.s32 %r56, %r52, {K_TILE_BYTES};        // V store base constant, c=2
    add.s32 %r42, %r41, 3;
    shr.u32 %r43, %r42, 5;
    and.b32 %r44, %r42, 31;
    xor.b32 %r45, %r44, %r43;
    shl.b32 %r46, %r45, 2;
    shl.b32 %r47, %r43, 7;
    add.s32 %r48, %r46, %r47;
    add.s32 %r48, %r48, %r40;
    add.s32 %r53, %r48, %r10;                  // K store base constant, c=3
    add.s32 %r57, %r53, {K_TILE_BYTES};        // V store base constant, c=3
    xor.b32 %r64, %r2, 1;
    xor.b32 %r65, %r2, 2;
    xor.b32 %r66, %r2, 3;
    shl.b32 %r60, %r2, 2;                      // (lane XOR 0)*4, read-side k=0
    shl.b32 %r61, %r64, 2;                     // (lane XOR 1)*4, k=1
    shl.b32 %r62, %r65, 2;                     // (lane XOR 2)*4, k=2
    shl.b32 %r63, %r66, 2;                     // (lane XOR 3)*4, k=3
    add.s32 %r70, %r10, %r60;                  // K read base constant, k=0
    add.s32 %r71, %r10, %r61;                  // k=1
    add.s32 %r72, %r10, %r62;                  // k=2
    add.s32 %r73, %r10, %r63;                  // k=3
    add.s32 %r80, %r70, {K_TILE_BYTES};        // V read base constant, k=0
    add.s32 %r81, %r71, {K_TILE_BYTES};        // k=1
    add.s32 %r82, %r72, {K_TILE_BYTES};        // k=2
    add.s32 %r83, %r73, {K_TILE_BYTES};        // k=3
    // -----------------------------------------------------------------
    // Software-pipelined double buffering of K/V tiles.
    //
    // Two ping-pong shared-memory buffers (BUF_STRIDE={BUF_STRIDE} bytes
    // apart) hold the K/V tile currently being consumed and the K/V tile
    // being prefetched for the next loop iteration.  This lets the
    // vectorized global->shared cooperative load of tile (j+1) overlap
    // with the FMA-heavy dot-product / softmax / PV-accumulate compute
    // of tile j, hiding global memory latency behind compute instead of
    // serialising load-then-compute behind a barrier every iteration.
    //
    // Prologue: prefetch tile 0 into buffer 0 before entering the loop.
    // -----------------------------------------------------------------
    mov.s32 %r90, %r50;                        // sK store target c=0 = buffer 0
    mov.s32 %r91, %r51;                        // c=1
    mov.s32 %r92, %r52;                        // c=2
    mov.s32 %r93, %r53;                        // c=3
    mov.s32 %r94, %r54;                        // sV store target c=0 = buffer 0
    mov.s32 %r95, %r55;                        // c=1
    mov.s32 %r96, %r56;                        // c=2
    mov.s32 %r97, %r57;                        // c=3
    add.s64 %rd18, %rd8, %rd14;                // K0_lane (by tid)
    add.s64 %rd19, %rd9, %rd14;                // V0_lane (by tid)
{_gen_coop_issue()}
{_gen_coop_unpack()}
    bar.sync 0;
    mov.u32 %r17, 0;                           // j = 0

$LOOP_START:
    and.b32 %r26, %r17, 1;                     // bit  = j & 1        (current-tile buffer select)
    xor.b32 %r27, %r26, 1;                     // nbit = 1 - bit      (next-tile buffer select)
    shl.b32 %r28, %r26, {BUF_STRIDE_LOG2};     // curroff (bytes into ping-pong region)
    shl.b32 %r29, %r27, {BUF_STRIDE_LOG2};     // nextoff (bytes into ping-pong region)
    add.s32 %r100, %r70, %r28;                 // sK read base k=0 (tile j, already resident)
    add.s32 %r101, %r71, %r28;                 // k=1
    add.s32 %r102, %r72, %r28;                 // k=2
    add.s32 %r103, %r73, %r28;                 // k=3
    add.s32 %r104, %r80, %r28;                 // sV read base k=0
    add.s32 %r105, %r81, %r28;                 // k=1
    add.s32 %r106, %r82, %r28;                 // k=2
    add.s32 %r107, %r83, %r28;                 // k=3
    add.s32 %r90, %r50, %r29;                  // sK store target c=0 (tile j+1, prefetch)
    add.s32 %r91, %r51, %r29;                  // c=1
    add.s32 %r92, %r52, %r29;                  // c=2
    add.s32 %r93, %r53, %r29;                  // c=3
    add.s32 %r94, %r54, %r29;                  // sV store target c=0
    add.s32 %r95, %r55, %r29;                  // c=1
    add.s32 %r96, %r56, %r29;                  // c=2
    add.s32 %r97, %r57, %r29;                  // c=3
    add.s32 %r18, %r17, 1;                     // j+1
    setp.lt.s32 %p2, %r18, %r0;                // (j+1) < N ?
    @!%p2 bra $SKIP_PREFETCH;
    mul.wide.s32 %rd15, %r18, %r7;             // (j+1)*rowbytes
    add.s64 %rd16, %rd8, %rd15;                // K(j+1)_ptr
    add.s64 %rd17, %rd9, %rd15;                // V(j+1)_ptr
    add.s64 %rd18, %rd16, %rd14;               // K(j+1)_lane (by tid)
    add.s64 %rd19, %rd17, %rd14;               // V(j+1)_lane (by tid)
{_gen_coop_issue()}
$SKIP_PREFETCH:
{_gen_dot_product()}
{_gen_warp_reduce()}
    mul.f32 %f7, %f5, %f0;             // score = partial * scale
    max.f32 %f8, %f2, %f7;             // new_m
    sub.f32 %f9, %f2, %f8;
    mul.f32 %f9, %f9, 0f3FB8AA3B;
    ex2.approx.f32 %f10, %f9;          // correction = exp(m_i - new_m)
    sub.f32 %f11, %f7, %f8;
    mul.f32 %f11, %f11, 0f3FB8AA3B;
    ex2.approx.f32 %f12, %f11;         // p = exp(score - new_m)
    mul.f32 %f3, %f3, %f10;
    add.f32 %f3, %f3, %f12;            // l_i = l_i*correction + p
{_gen_acc_update()}
    mov.f32 %f2, %f8;                  // m_i = new_m
    @!%p2 bra $SKIP_UNPACK;
{_gen_coop_unpack()}
$SKIP_UNPACK:
    bar.sync 0;                        // (a) makes this iteration's tile-(j+1) prefetch
                                        //     visible before it is read as "current" next
                                        //     iteration; (b) makes sure this iteration's
                                        //     reads of tile j finish before the following
                                        //     iteration overwrites that same buffer slot.
    add.s32 %r17, %r17, 1;
    setp.lt.s32 %p1, %r17, %r0;
    @%p1 bra $LOOP_START;

    rcp.rn.f32 %f14, %f3;              // inv_l = 1 / l_i

{_gen_output_store()}

    ret;
