def validate_generated_code():
    """Sanity check: build the PTX module and confirm the entry exists."""
    module = PtxModule(PTX_SOURCE)
    fn = module.function("flash_attn_kernel")
    assert fn is not None, "flash_attn_kernel entry point not found in PTX module"
    return True


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._module = None

    def _get_module(self):
        if self._module is None:
            self._module = PtxModule(PTX_SOURCE)
        return self._module

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        assert Q.is_cuda and K.is_cuda and V.is_cuda, "Q, K, V must be CUDA tensors"
        assert Q.dtype == torch.float16 and K.dtype == torch.float16 and V.dtype == torch.float16, \
            "Only float16 is supported"
        assert Q.dim() == 4, "Q, K, V must be 4D [B,H,N,D]"

        Qc = Q.contiguous()
        Kc = K.contiguous()
        Vc = V.contiguous()

        B, H, N, D = Qc.shape
        assert D == D_MODEL, f"kernel specialised for D={D_MODEL}, got {D}"
        assert N % ROWS_PER_BLOCK == 0, "sequence length must be divisible by rows-per-block"
        assert Kc.shape == Qc.shape and Vc.shape == Qc.shape, "K/V shape mismatch"

        O = torch.empty_like(Qc)
        scale = 1.0 / math.sqrt(float(D))

        module = self._get_module()

        grid = (N // ROWS_PER_BLOCK, B * H, 1)
        block = (LANES, ROWS_PER_BLOCK, 1)
        stream = torch.cuda.current_stream(Qc.device)

        module.launch(
            "flash_attn_kernel",
            grid,
            block,
            [
                u64(Qc.data_ptr()),
                u64(Kc.data_ptr()),
                u64(Vc.data_ptr()),
                u64(O.data_ptr()),
                i32(N),
                i32(D),
                f32(scale),
            ],
            stream=stream,
        )

        return O


