import math
import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Fixed problem geometry for this kernel (matches the reference CuTe kernel
# specialised for embedding_dimension == 1024, LANES == 32).
# ---------------------------------------------------------------------------
LANES = 32                       # warp width
DPER = 32                        # elements per lane  (D_MODEL / LANES)
D_MODEL = LANES * DPER           # 1024
ROWS_PER_BLOCK = 8               # query rows handled per block (one warp/row)
THREADS = LANES * ROWS_PER_BLOCK # 256 threads per block
COOP_ITERS = D_MODEL // THREADS  # 4  (cooperative K/V load iterations)

# ---------------------------------------------------------------------------
# Shared-memory layout for K/V tiles.
#
# The original layout packed fp16 values tightly (2 bytes / element).  Since
# the dot-product / accumulation loops access shared memory with a per-lane
# stride of exactly 2 bytes, adjacent lanes fall into the SAME 4-byte shared
# memory bank pair (bank_id = (lane*2)//4 = lane//2), producing a 2-way bank
# conflict on every one of the DPER=32 shared loads per K/V tile, repeated
# for every tile iteration of the flash-attention loop.  This is a hot path
# executed (N / ROWS_PER_BLOCK) * DPER * 2 times per block.
#
# To remove the conflict we pad each fp16 element out to a full 4-byte slot
# in shared memory (PAD_STRIDE = 4).  With this layout, lane*4 maps exactly
# one lane to one bank (bank_id = lane), eliminating the bank conflict
# entirely while leaving the actual stored/loaded values (u16) unchanged.
# Global-memory addressing (which is still tightly packed fp16, 2 bytes /
# element) is unaffected by this change.
# ---------------------------------------------------------------------------
PAD_STRIDE = 4                                  # bytes per element in shared mem (padded)
K_TILE_BYTES = D_MODEL * PAD_STRIDE             # bytes for one padded K (or V) tile
BUF_STRIDE = 2 * K_TILE_BYTES                   # bytes per ping-pong buffer slot (K tile + V tile)
BUF_STRIDE_LOG2 = BUF_STRIDE.bit_length() - 1   # log2(BUF_STRIDE); BUF_STRIDE is a power of two
SMEM_BYTES = 2 * BUF_STRIDE                     # two ping-pong buffers for software-pipelined K/V loads
STAGE_PER_ARRAY = THREADS * COOP_ITERS * 2       # bytes: contiguous per-thread cp.async staging region for K (or V)
STAGE_BYTES = 2 * STAGE_PER_ARRAY                # staging area for both K and V tiles (async landing zone)


def _off(x: int) -> str:
    return f"+{x}" if x else ""


def _gen_q_load() -> str:
    lines = []
    for i in range(DPER):
        off = _off(i * LANES * 2)
        lines.append(f"    ld.global.nc.u16 %hq{i}, [%rd12{off}];")
        lines.append(f"    cvt.f32.f16 %q{i}, %hq{i};")
    return "\n".join(lines)


def _gen_acc_init() -> str:
    return "\n".join(f"    mov.f32 %acc{i}, 0f00000000;" for i in range(DPER))


def _gen_coop_issue() -> str:
    # Asynchronous (cp.async, sm_80+) global -> shared staging copy.
    # Instead of round-tripping the vectorized per-thread K/V tile chunk
    # through registers (ld.global.v4 -> registers -> st.shared), the
    # 8-byte-per-thread K and V chunks are copied directly from global
    # memory into a small contiguous "staging" landing zone in shared
    # memory using the hardware async-copy engine.  This removes the
    # load from the normal register/ALU issue pipeline and lets the
    # copy run in the background while the SM continues issuing the
    # current tile's dot-product / softmax / PV-accumulate instructions.
    # The matching cp.async.wait_group + scatter-unpack (see
    # _gen_coop_unpack) is deferred until just before the staged data is
    # actually needed, maximising the overlap window with compute.
    lines = []
    lines.append("    cp.async.ca.shared.global [%r122], [%rd18], 8;")
    lines.append("    cp.async.ca.shared.global [%r123], [%rd19], 8;")
    lines.append("    cp.async.commit_group;")
    return "\n".join(lines)
def _gen_coop_unpack() -> str:
    # Wait for the async copy issued by _gen_coop_issue() to land in the
    # staging area, then scatter the tightly-packed staged halfwords out
    # to their bank-conflict-free, XOR-swizzled, padded destinations in
    # the real ping-pong K/V buffer.  The store-side destination
    # addressing (precomputed swizzled bases %r90..%r97) is unchanged
    # from the previous synchronous-load implementation.
    #
    # The COOP_ITERS=4 contiguous halfwords staged per thread (8 bytes)
    # are now pulled out of shared memory with a single vectorized
    # ld.shared.v4.u16 instead of four separate scalar ld.shared.u16
    # instructions.  This halves the number of shared-memory load
    # instructions issued on this hot path (executed on essentially
    # every flash-attention tile iteration) while reading the exact
    # same bytes from the exact same (naturally 8-byte aligned)
    # staging address, so the unpacked per-lane values are unchanged.
    lines = []
    lines.append("    cp.async.wait_group 0;")
    coopk_regs = ", ".join(f"%hcoopk{c}" for c in range(COOP_ITERS))
    coopv_regs = ", ".join(f"%hcoopv{c}" for c in range(COOP_ITERS))
    lines.append(f"    ld.shared.v4.u16 {{{coopk_regs}}}, [%r122];")
    lines.append(f"    ld.shared.v4.u16 {{{coopv_regs}}}, [%r123];")
    for c in range(COOP_ITERS):
        lines.append(f"    st.shared.u16 [%r{90 + c}], %hcoopk{c};")
        lines.append(f"    st.shared.u16 [%r{94 + c}], %hcoopv{c};")
    return "\n".join(lines)


def _gen_dot_product() -> str:
    # Break the single 32-long sequential FMA dependency chain into
    # DOT_GROUPS independent partial-sum chains so the instruction
    # scheduler can overlap FMA latency across groups (higher ILP)
    # instead of serialising all DPER multiply-adds into one long
    # dependent chain through a single accumulator register.  Each
    # element also gets its own cvt.f32.f16 destination register
    # (instead of reusing a single %f4 scratch register) to remove
    # artificial write-after-write dependencies between iterations.
    #
    # DOT_GROUPS is raised from 4 to 8 (GROUP_SIZE 4 instead of 8):
    # doubling the number of independent partial-sum accumulators
    # halves the length of each FMA dependency chain (from 8 dependent
    # FMAs down to 4), giving the instruction scheduler more
    # independent work to interleave and further hiding per-FMA
    # latency, at the cost of a slightly deeper (but still cheap,
    # log2(8)=3-level) final tree-reduction of the partial sums.
    DOT_GROUPS = 8
    GROUP_SIZE = DPER // DOT_GROUPS
    lines = []
    for i in range(DPER):
        base_reg = 100 + (i % 4)
        off = _off(i * LANES * PAD_STRIDE)
        lines.append(f"    ld.shared.u16 %hk{i}, [%r{base_reg}{off}];")
        lines.append(f"    cvt.f32.f16 %g{i}, %hk{i};")
    for g in range(DOT_GROUPS):
        base = g * GROUP_SIZE
        lines.append(f"    mul.f32 %gp{g}, %q{base}, %g{base};")
        for j in range(1, GROUP_SIZE):
            idx = base + j
            lines.append(f"    fma.rn.f32 %gp{g}, %q{idx}, %g{idx}, %gp{g};")
    lines.append("    add.f32 %gp0, %gp0, %gp1;")
    lines.append("    add.f32 %gp2, %gp2, %gp3;")
    lines.append("    add.f32 %gp4, %gp4, %gp5;")
    lines.append("    add.f32 %gp6, %gp6, %gp7;")
    lines.append("    add.f32 %gp0, %gp0, %gp2;")
    lines.append("    add.f32 %gp4, %gp4, %gp6;")
    lines.append("    add.f32 %f5, %gp0, %gp4;")
    return "\n".join(lines)


def _gen_warp_reduce() -> str:
    lines = []
    for off in (16, 8, 4, 2, 1):
        lines.append("    mov.b32 %r20, %f5;")
        lines.append(f"    shfl.sync.bfly.b32 %r21|%p0, %r20, {off}, 31, -1;")
        lines.append("    mov.b32 %f6, %r21;")
        lines.append("    add.f32 %f5, %f5, %f6;")
    return "\n".join(lines)


def _gen_acc_update() -> str:
    lines = []
    for i in range(DPER):
        base_reg = 104 + (i % 4)
        off = _off(i * LANES * PAD_STRIDE)
        lines.append(f"    ld.shared.u16 %hv{i}, [%r{base_reg}{off}];")
        lines.append(f"    cvt.f32.f16 %f13, %hv{i};")
        lines.append(f"    mul.f32 %acc{i}, %acc{i}, %f10;")
        lines.append(f"    fma.rn.f32 %acc{i}, %f12, %f13, %acc{i};")
    return "\n".join(lines)


def _gen_output_store() -> str:
    lines = []
    for i in range(DPER):
        off = _off(i * LANES * 2)
        lines.append(f"    mul.f32 %f15, %acc{i}, %f14;")
        lines.append(f"    cvt.rn.f16.f32 %ho{i}, %f15;")
        lines.append(f"    st.global.u16 [%rd13{off}], %ho{i};")
    return "\n".join(lines)


def _build_ptx() -> str:
    body = f"""
.version 8.7
.target sm_89
.address_size 64

// Flash-attention style fused SDPA kernel.
// One warp handles one query row; ROWS_PER_BLOCK warps per block cooperate
// to stage K/V tiles into shared memory.  Specialised for D_MODEL={D_MODEL},
// LANES={LANES}, DPER={DPER}, ROWS_PER_BLOCK={ROWS_PER_BLOCK}.
//
// Shared-memory K/V tiles are padded to PAD_STRIDE={PAD_STRIDE} bytes per
// fp16 element (instead of the natural 2 bytes) so that per-lane accesses
// with stride LANES*PAD_STRIDE map one lane to one shared-memory bank,
// removing the 2-way bank conflicts present in the tightly-packed layout.
.visible .entry flash_attn_kernel(
    .param .u64 p_Q,
    .param .u64 p_K,
    .param .u64 p_V,
    .param .u64 p_O,
    .param .u32 p_N,
    .param .u32 p_D,
    .param .f32 p_scale
)
// -----------------------------------------------------------------
// Launch-bound specialisation: the host-side launch glue always
// dispatches this kernel with block dimensions (LANES, ROWS_PER_BLOCK,
// 1) = (32, 8, 1) (see ModelNew.forward below).  Declaring this exact
// CTA shape via .reqntid lets ptxas specialise register allocation,
// index/bounds computation, and instruction scheduling for the known,
// fixed thread-block geometry instead of generating code that has to
// remain correct for an arbitrary block shape.  This is a semantics-
// preserving launch-configuration hint (no change to addressing,
// synchronization, or numerical behaviour) that can improve achieved
// occupancy / reduce register spilling relative to the unconstrained
// compilation used previously.
// -----------------------------------------------------------------
.reqntid 32, 8, 1
{{
    .reg .pred %p<4>;
    .reg .b16 %hq<{DPER}>;
    .reg .b16 %hk<{DPER}>;
    .reg .b16 %hv<{DPER}>;
    .reg .b16 %ho<{DPER}>;
    .reg .b16 %hcoopk<{COOP_ITERS}>;
    .reg .b16 %hcoopv<{COOP_ITERS}>;
    .reg .f32 %q<{DPER}>;
    .reg .f32 %acc<{DPER}>;
    .reg .f32 %f<16>;
    .reg .b32 %r<140>;
    .reg .b64 %rd<22>;

    .shared .align 16 .b8 smem_buf[{SMEM_BYTES}];
    .shared .align 16 .b8 stage_buf[{STAGE_BYTES}];

    ld.param.u64 %rd0, [p_Q];
    ld.param.u64 %rd1, [p_K];
    ld.param.u64 %rd2, [p_V];
    ld.param.u64 %rd3, [p_O];
    ld.param.u32 %r0, [p_N];
    ld.param.u32 %r1, [p_D];
    ld.param.f32 %f0, [p_scale];

