    mov.u32 %r3, %tid.y;               // warp id / row within tile (0..7)
    mov.u32 %r4, %ctaid.x;             // row tile index
    mov.u32 %r5, %ctaid.y;             // combined (batch*head) index

    mad.lo.s32 %r6, %r4, {ROWS_PER_BLOCK}, %r3;   // q_row = tile*ROWS_PER_BLOCK + warp

    mul.lo.s32 %r7, %r1, 2;            // rowbytes  = D*2
    mul.lo.s32 %r8, %r0, %r7;          // NDbytes   = N*D*2

    mul.wide.s32 %rd4, %r5, %r8;       // bh_offset  = bh * NDbytes
