    add.s64 %rd12, %rd7, %rd11;        // Q_lane_ptr
    add.s64 %rd13, %rd10, %rd11;       // O_lane_ptr

{_gen_q_load()}

    mov.f32 %f2, 0fFF800000;           // m_i = -inf
    mov.f32 %f3, 0f00000000;           // l_i = 0
{_gen_acc_init()}

    mad.lo.s32 %r9, %r3, {LANES}, %r2;         // tid = warp*LANES + lane  (0..THREADS-1)
    mul.wide.s32 %rd14, %r9, {COOP_ITERS * 2};        // tid_off64 (global mem, contiguous per-thread group of COOP_ITERS elems)
