    and.b32 %r44, %r42, 31;
    xor.b32 %r45, %r44, %r43;
    shl.b32 %r46, %r45, 2;
    shl.b32 %r47, %r43, 7;
    add.s32 %r48, %r46, %r47;
    add.s32 %r48, %r48, %r40;
    add.s32 %r51, %r48, %r10;                  // K store base constant, c=1
    add.s32 %r55, %r51, {K_TILE_BYTES};        // V store base constant, c=1
    add.s32 %r42, %r41, 2;
    shr.u32 %r43, %r42, 5;
    and.b32 %r44, %r42, 31;
    xor.b32 %r45, %r44, %r43;
    shl.b32 %r46, %r45, 2;
    shl.b32 %r47, %r43, 7;
    add.s32 %r48, %r46, %r47;
    add.s32 %r48, %r48, %r40;
    add.s32 %r52, %r48, %r10;                  // K store base constant, c=2
    add.s32 %r56, %r52, {K_TILE_BYTES};        // V store base constant, c=2
    add.s32 %r42, %r41, 3;
    shr.u32 %r43, %r42, 5;
    and.b32 %r44, %r42, 31;
    xor.b32 %r45, %r44, %r43;
    shl.b32 %r46, %r45, 2;
    shl.b32 %r47, %r43, 7;
    add.s32 %r48, %r46, %r47;
    add.s32 %r48, %r48, %r40;
    add.s32 %r53, %r48, %r10;                  // K store base constant, c=3
    add.s32 %r57, %r53, {K_TILE_BYTES};        // V store base constant, c=3
    xor.b32 %r64, %r2, 1;
    xor.b32 %r65, %r2, 2;
    xor.b32 %r66, %r2, 3;
    shl.b32 %r60, %r2, 2;                      // (lane XOR 0)*4, read-side k=0
    shl.b32 %r61, %r64, 2;                     // (lane XOR 1)*4, k=1
    shl.b32 %r62, %r65, 2;                     // (lane XOR 2)*4, k=2
    shl.b32 %r63, %r66, 2;                     // (lane XOR 3)*4, k=3
    add.s32 %r70, %r10, %r60;                  // K read base constant, k=0
    add.s32 %r71, %r10, %r61;                  // k=1
    add.s32 %r72, %r10, %r62;                  // k=2
    add.s32 %r73, %r10, %r63;                  // k=3
    add.s32 %r80, %r70, {K_TILE_BYTES};        // V read base constant, k=0
    add.s32 %r81, %r71, {K_TILE_BYTES};        // k=1
    add.s32 %r82, %r72, {K_TILE_BYTES};        // k=2
    add.s32 %r83, %r73, {K_TILE_BYTES};        // k=3
    // -----------------------------------------------------------------
    // Software-pipelined double buffering of K/V tiles.
    //
    // Two ping-pong shared-memory buffers (BUF_STRIDE={BUF_STRIDE} bytes
    // apart) hold the K/V tile currently being consumed and the K/V tile
    // being prefetched for the next loop iteration.  This lets the
    // vectorized global->shared cooperative load of tile (j+1) overlap
    // with the FMA-heavy dot-product / softmax / PV-accumulate compute
    // of tile j, hiding global memory latency behind compute instead of
    // serialising load-then-compute behind a barrier every iteration.
    //
    // Prologue: prefetch tile 0 into buffer 0 before entering the loop.
    // -----------------------------------------------------------------
    mov.s32 %r90, %r50;                        // sK store target c=0 = buffer 0
    mov.s32 %r91, %r51;                        // c=1
    mov.s32 %r92, %r52;                        // c=2
    mov.s32 %r93, %r53;                        // c=3
    mov.s32 %r94, %r54;                        // sV store target c=0 = buffer 0
    mov.s32 %r95, %r55;                        // c=1
    mov.s32 %r96, %r56;                        // c=2
    mov.s32 %r97, %r57;                        // c=3
