import math
import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Fixed problem geometry for this kernel (matches the reference CuTe kernel
# specialised for embedding_dimension == 1024, LANES == 32).
# ---------------------------------------------------------------------------
LANES = 32                       # warp width
DPER = 32                        # elements per lane  (D_MODEL / LANES)
D_MODEL = LANES * DPER           # 1024
ROWS_PER_BLOCK = 8               # query rows handled per block (one warp/row)
THREADS = LANES * ROWS_PER_BLOCK # 256 threads per block
COOP_ITERS = D_MODEL // THREADS  # 4  (cooperative K/V load iterations)

# ---------------------------------------------------------------------------
# Shared-memory layout for K/V tiles.
#
# The original layout packed fp16 values tightly (2 bytes / element).  Since
# the dot-product / accumulation loops access shared memory with a per-lane
# stride of exactly 2 bytes, adjacent lanes fall into the SAME 4-byte shared
# memory bank pair (bank_id = (lane*2)//4 = lane//2), producing a 2-way bank
# conflict on every one of the DPER=32 shared loads per K/V tile, repeated
# for every tile iteration of the flash-attention loop.  This is a hot path
# executed (N / ROWS_PER_BLOCK) * DPER * 2 times per block.
#
# To remove the conflict we pad each fp16 element out to a full 4-byte slot
# in shared memory (PAD_STRIDE = 4).  With this layout, lane*4 maps exactly
# one lane to one bank (bank_id = lane), eliminating the bank conflict
# entirely while leaving the actual stored/loaded values (u16) unchanged.
# Global-memory addressing (which is still tightly packed fp16, 2 bytes /
# element) is unaffected by this change.
# ---------------------------------------------------------------------------
PAD_STRIDE = 4                                  # bytes per element in shared mem (padded)
K_TILE_BYTES = D_MODEL * PAD_STRIDE             # bytes for one padded K (or V) tile
BUF_STRIDE = 2 * K_TILE_BYTES                   # bytes per ping-pong buffer slot (K tile + V tile)
BUF_STRIDE_LOG2 = BUF_STRIDE.bit_length() - 1   # log2(BUF_STRIDE); BUF_STRIDE is a power of two
SMEM_BYTES = 2 * BUF_STRIDE                     # two ping-pong buffers for software-pipelined K/V loads


def _off(x: int) -> str:
    return f"+{x}" if x else ""


def _gen_q_load() -> str:
    lines = []
    for i in range(DPER):
        off = _off(i * LANES * 2)
        lines.append(f"    ld.global.nc.u16 %hq{i}, [%rd12{off}];")
        lines.append(f"    cvt.f32.f16 %q{i}, %hq{i};")
    return "\n".join(lines)


def _gen_acc_init() -> str:
    return "\n".join(f"    mov.f32 %acc{i}, 0f00000000;" for i in range(DPER))


def _gen_coop_load() -> str:
    # Bank-conflict-free cooperative store: each thread's COOP_ITERS (=4)
    # contiguous global elements are still loaded with a single vectorized
    # ld.global.v4.u16 (fully coalesced, unchanged from before), but the
    # shared-memory *store* destinations are now selected from four
    # precomputed, XOR-swizzled base registers (one per c = 0..3) instead of
    # a single tid-linear base + constant offset.  The previous linear
    # addressing caused adjacent lanes' stores (stride = COOP_ITERS*PAD_STRIDE
    # = 16B) to collide on only 8 of the 32 shared-memory banks (4-way bank
    # conflict) for every one of the COOP_ITERS*2 stores issued per K/V tile
    # load.  The swizzled bases (precomputed once outside the main loop; see
    # setup code above the pipeline prologue) restore a full 32-way bank
    # spread while leaving the read-side addressing (already conflict-free)
    # and the global-memory coalescing pattern unchanged.
    lines = []
    lines.append("    ld.global.nc.v4.u16 {%hcoopk0, %hcoopk1, %hcoopk2, %hcoopk3}, [%rd18];")
    lines.append("    ld.global.nc.v4.u16 {%hcoopv0, %hcoopv1, %hcoopv2, %hcoopv3}, [%rd19];")
    for c in range(COOP_ITERS):
        lines.append(f"    st.shared.u16 [%r{90 + c}], %hcoopk{c};")
        lines.append(f"    st.shared.u16 [%r{94 + c}], %hcoopv{c};")
    return "\n".join(lines)


def _gen_dot_product() -> str:
    # Break the single 32-long sequential FMA dependency chain into
    # DOT_GROUPS independent partial-sum chains so the instruction
    # scheduler can overlap FMA latency across groups (higher ILP)
    # instead of serialising all DPER multiply-adds into one long
    # dependent chain through a single accumulator register.  Each
    # element also gets its own cvt.f32.f16 destination register
    # (instead of reusing a single %f4 scratch register) to remove
    # artificial write-after-write dependencies between iterations.
    DOT_GROUPS = 4
    GROUP_SIZE = DPER // DOT_GROUPS
    lines = []
    for i in range(DPER):
        base_reg = 100 + (i % 4)
        off = _off(i * LANES * PAD_STRIDE)
        lines.append(f"    ld.shared.u16 %hk{i}, [%r{base_reg}{off}];")
        lines.append(f"    cvt.f32.f16 %g{i}, %hk{i};")
    for g in range(DOT_GROUPS):
        base = g * GROUP_SIZE
        lines.append(f"    mul.f32 %gp{g}, %q{base}, %g{base};")
        for j in range(1, GROUP_SIZE):
            idx = base + j
            lines.append(f"    fma.rn.f32 %gp{g}, %q{idx}, %g{idx}, %gp{g};")
    lines.append("    add.f32 %gp0, %gp0, %gp1;")
    lines.append("    add.f32 %gp2, %gp2, %gp3;")
    lines.append("    add.f32 %f5, %gp0, %gp2;")
    return "\n".join(lines)


def _gen_warp_reduce() -> str:
    lines = []
    for off in (16, 8, 4, 2, 1):
        lines.append("    mov.b32 %r20, %f5;")
        lines.append(f"    shfl.sync.bfly.b32 %r21|%p0, %r20, {off}, 31, -1;")
        lines.append("    mov.b32 %f6, %r21;")
        lines.append("    add.f32 %f5, %f5, %f6;")
    return "\n".join(lines)


def _gen_acc_update() -> str:
    lines = []
    for i in range(DPER):
        base_reg = 104 + (i % 4)
        off = _off(i * LANES * PAD_STRIDE)
        lines.append(f"    ld.shared.u16 %hv{i}, [%r{base_reg}{off}];")
        lines.append(f"    cvt.f32.f16 %f13, %hv{i};")
        lines.append(f"    mul.f32 %acc{i}, %acc{i}, %f10;")
        lines.append(f"    fma.rn.f32 %acc{i}, %f12, %f13, %acc{i};")
    return "\n".join(lines)


def _gen_output_store() -> str:
    lines = []
    for i in range(DPER):
        off = _off(i * LANES * 2)
        lines.append(f"    mul.f32 %f15, %acc{i}, %f14;")
        lines.append(f"    cvt.rn.f16.f32 %ho{i}, %f15;")
        lines.append(f"    st.global.u16 [%rd13{off}], %ho{i};")
    return "\n".join(lines)


