    shl.b32 %r61, %r64, 2;                     // (lane XOR 1)*4, k=1
    shl.b32 %r62, %r65, 2;                     // (lane XOR 2)*4, k=2
    shl.b32 %r63, %r66, 2;                     // (lane XOR 3)*4, k=3
    add.s32 %r70, %r10, %r60;                  // K read base constant, k=0
    add.s32 %r71, %r10, %r61;                  // k=1
    add.s32 %r72, %r10, %r62;                  // k=2
    add.s32 %r73, %r10, %r63;                  // k=3
    add.s32 %r80, %r70, {K_TILE_BYTES};        // V read base constant, k=0
    add.s32 %r81, %r71, {K_TILE_BYTES};        // k=1
    add.s32 %r82, %r72, {K_TILE_BYTES};        // k=2
    add.s32 %r83, %r73, {K_TILE_BYTES};        // k=3
    // -----------------------------------------------------------------
    // Software-pipelined double buffering of K/V tiles.
    //
    // Two ping-pong shared-memory buffers (BUF_STRIDE={BUF_STRIDE} bytes
    // apart) hold the K/V tile currently being consumed and the K/V tile
    // being prefetched for the next loop iteration.  This lets the
    // vectorized global->shared cooperative load of tile (j+1) overlap
    // with the FMA-heavy dot-product / softmax / PV-accumulate compute
    // of tile j, hiding global memory latency behind compute instead of
    // serialising load-then-compute behind a barrier every iteration.
    //
    // Prologue: prefetch tile 0 into buffer 0 before entering the loop.
    // -----------------------------------------------------------------
    mov.s32 %r90, %r50;                        // sK store target c=0 = buffer 0
    mov.s32 %r91, %r51;                        // c=1
    mov.s32 %r92, %r52;                        // c=2
    mov.s32 %r93, %r53;                        // c=3
    mov.s32 %r94, %r54;                        // sV store target c=0 = buffer 0
    mov.s32 %r95, %r55;                        // c=1
    mov.s32 %r96, %r56;                        // c=2
    mov.s32 %r97, %r57;                        // c=3
    add.s64 %rd18, %rd8, %rd14;                // K0_lane (by tid)
    add.s64 %rd19, %rd9, %rd14;                // V0_lane (by tid)
{_gen_coop_load()}
    bar.sync 0;
    mov.u32 %r17, 0;                           // j = 0

$LOOP_START:
    and.b32 %r26, %r17, 1;                     // bit  = j & 1        (current-tile buffer select)
    xor.b32 %r27, %r26, 1;                     // nbit = 1 - bit      (next-tile buffer select)
    shl.b32 %r28, %r26, {BUF_STRIDE_LOG2};     // curroff (bytes into ping-pong region)
    shl.b32 %r29, %r27, {BUF_STRIDE_LOG2};     // nextoff (bytes into ping-pong region)
    add.s32 %r100, %r70, %r28;                 // sK read base k=0 (tile j, already resident)
    add.s32 %r101, %r71, %r28;                 // k=1
    add.s32 %r102, %r72, %r28;                 // k=2
    add.s32 %r103, %r73, %r28;                 // k=3
    add.s32 %r104, %r80, %r28;                 // sV read base k=0
    add.s32 %r105, %r81, %r28;                 // k=1
    add.s32 %r106, %r82, %r28;                 // k=2
    add.s32 %r107, %r83, %r28;                 // k=3
    add.s32 %r90, %r50, %r29;                  // sK store target c=0 (tile j+1, prefetch)
    add.s32 %r91, %r51, %r29;                  // c=1
    add.s32 %r92, %r52, %r29;                  // c=2
    add.s32 %r93, %r53, %r29;                  // c=3
    add.s32 %r94, %r54, %r29;                  // sV store target c=0
    add.s32 %r95, %r55, %r29;                  // c=1
    add.s32 %r96, %r56, %r29;                  // c=2
    add.s32 %r97, %r57, %r29;                  // c=3
    add.s32 %r18, %r17, 1;                     // j+1
    setp.lt.s32 %p2, %r18, %r0;                // (j+1) < N ?
    @!%p2 bra $SKIP_PREFETCH;
    mul.wide.s32 %rd15, %r18, %r7;             // (j+1)*rowbytes
    add.s64 %rd16, %rd8, %rd15;                // K(j+1)_ptr
    add.s64 %rd17, %rd9, %rd15;                // V(j+1)_ptr
    add.s64 %rd18, %rd16, %rd14;               // K(j+1)_lane (by tid)
    add.s64 %rd19, %rd17, %rd14;               // V(j+1)_lane (by tid)
{_gen_coop_load()}
$SKIP_PREFETCH:
{_gen_dot_product()}
{_gen_warp_reduce()}
    mul.f32 %f7, %f5, %f0;             // score = partial * scale
    max.f32 %f8, %f2, %f7;             // new_m
    sub.f32 %f9, %f2, %f8;
    mul.f32 %f9, %f9, 0f3FB8AA3B;
    ex2.approx.f32 %f10, %f9;          // correction = exp(m_i - new_m)
    sub.f32 %f11, %f7, %f8;
    mul.f32 %f11, %f11, 0f3FB8AA3B;
    ex2.approx.f32 %f12, %f11;         // p = exp(score - new_m)
    mul.f32 %f3, %f3, %f10;
    add.f32 %f3, %f3, %f12;            // l_i = l_i*correction + p
{_gen_acc_update()}
    mov.f32 %f2, %f8;                  // m_i = new_m
    bar.sync 0;                        // (a) makes this iteration's tile-(j+1) prefetch
                                        //     visible before it is read as "current" next
                                        //     iteration; (b) makes sure this iteration's
                                        //     reads of tile j finish before the following
                                        //     iteration overwrites that same buffer slot.
    add.s32 %r17, %r17, 1;
    setp.lt.s32 %p1, %r17, %r0;
    @%p1 bra $LOOP_START;

    rcp.rn.f32 %f14, %f3;              // inv_l = 1 / l_i

{_gen_output_store()}

